it('caches function-valued tool definitions by schema reference', async () => {
  const registry = new ToolRegistry();
  const schema = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
  registry.register(
    () => ({name: 'fn', description: 'd', inputSchema: schema}),
    async () => 'ok'
  );

  await registry.execute('fn', {b: 123});

  // @ts-expect-error - accessing private ajv to spy on compile
  const spy = jest.spyOn(registry.ajv, 'compile');
